def solve(a, b):
    # Guard against None inputs, treat them as empty strings
    if a is None:
        a = ''
    if b is None:
        b = ''
    m, n = len(a), len(b)
    # Use a DP table with O(min(m,n)) space for efficiency and safety
    if n < m:
        # Ensure that we iterate over the shorter string in the inner loop
        a, b = b, a
        m, n = n, m
    previous = list(range(m + 1))  # dp for previous row (b's prefix)
    for i in range(1, n + 1):
        current = [i] + [0] * m
        for j in range(1, m + 1):
            if a[j - 1] == b[i - 1]:
                current[j] = previous[j - 1]
            else:
                current[j] = 1 + min(previous[j],      # deletion
                                   current[j - 1],   # insertion
                                   previous[j - 1])   # substitution
        previous = current
    return previous[m]

