def solve(grid):
    """Count islands (connected components of 1s) in a possibly jagged grid.
    grid: list of lists, where each sublist may have varying length.
    Cells connect up, down, left, right.
    Returns integer count.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited structure mirrors grid shape
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for ni,nj in neighbors(i,j):
                if not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni,nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i,j)
    return count

